#pragma once

class Buffer {
public:
    static inline int instance_count = 0;

    explicit Buffer(int size) {
        data_ = new int[size];
        instance_count++;
    }

    ~Buffer() {
        // BUG: does not delete[] data_ and does not decrement instance_count
    }

private:
    int* data_;
};

test_setup_files.test_leak_main.cpp:
#include "buffer.h"
#include <cassert>
#include <iostream>

int main() {
    assert(Buffer::instance_count == 0);
    {
        Buffer a(16);
        assert(Buffer::instance_count == 1);
        Buffer b(32);
        assert(Buffer::instance_count == 2);
    }
    assert(Buffer::instance_count == 0);

    for (int i = 0; i < 200000; i++) {
        Buffer c(8);
        assert(Buffer::instance_count == 1);
    }
    assert(Buffer::instance_count == 0);

    std::cout << "PASS" << std::endl;
    return 0;
}
